import{_ as t,m as d,k as o,ah as c}from"./chunks/framework.HEc25T99.js";const p=JSON.parse('{"title":"API & Endpoints","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/development/api-endpoints.md","filePath":"src/en/developers/development/api-endpoints.md"}'),a={name:"developers/development/api-endpoints.md"};function i(s,e,n,r,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c(`<h1 id="api-endpoints" tabindex="-1">API &amp; Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API &amp; Endpoints&quot;">​</a></h1><p>Creopse exposes a complete REST API under <code>/api</code> — it&#39;s what the admin interface itself consumes, but also any external client (mobile app, third-party integration) that wants to serve the content somewhere other than through the built-in frontend.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><h3 id="response-format" tabindex="-1">Response format <a class="header-anchor" href="#response-format" aria-label="Permalink to &quot;Response format&quot;">​</a></h3><p>Every response follows the same JSON envelope:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Optional&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;errorCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Optional&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>data</code> holds the result (object, array, or paginated object depending on the endpoint); <code>message</code>/<code>errorCode</code> only appear when relevant (errors in particular).</p><h3 id="key-casing" tabindex="-1">Key casing <a class="header-anchor" href="#key-casing" aria-label="Permalink to &quot;Key casing&quot;">​</a></h3><p>JSON keys exchanged with the client are <strong>camelCase</strong>, automatically converted to snake_case server-side and back — always send and receive camelCase, regardless of the internal convention (database, PHP code).</p><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>See <a href="./authentication.html">Authentication</a> for the full picture. In short: <code>auth:sanctum</code> protects most write routes and some read routes, accepting either a session (admin interface) or a Bearer token (external clients) indifferently. Each group below states what&#39;s public.</p><h3 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h3><p>Every route under <code>/api</code> is subject to a limit (<code>CREOPSE_RATE_LIMIT</code>, default <code>600</code>/minute), applied per IP or per authenticated user depending on <code>rate_limit_by</code> — see <a href="./configuration.html#rate-limiting">Configuration</a>.</p><h3 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h3><p>Allowed origins match the domains listed in <code>SANCTUM_STATEFUL_DOMAINS</code> (see <a href="./authentication.html">Authentication</a>) — <code>https://</code> only in production, <code>http://</code>/<code>https://</code> in development. Cookies (<code>supports_credentials</code>) are supported for admin interface requests.</p><h2 id="content-pages-sections-menus-content-models-permalinks" tabindex="-1">Content (pages, sections, menus, content models, permalinks) <a class="header-anchor" href="#content-pages-sections-menus-content-models-permalinks" aria-label="Permalink to &quot;Content (pages, sections, menus, content models, permalinks)&quot;">​</a></h2><p>The core of the API — consumed both by the admin interface (writes) and by frontend templates (reads).</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/pages</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/pages/{page}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/pages</code>, <code>/pages/{page}</code></td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/pages/position</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/sections</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/sections/{section}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/section-data/{sectionSlug}/source/{pageSlug}/link/{linkId}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/sections</code>, <code>/sections/{section}</code></td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/sections/{section}/data-source-page</code>, <code>/sections/{section}/duplicate</code>, <code>/sections/{section}/copy-data</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/sections/{slug}/link/{linkId}/page/{pageId}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/menus</code>, <code>/menus/{menu}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/menus</code>, <code>/menus/{menu}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/menu/items</code>, <code>/menu/items/{menuItem}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/menu/items</code>, <code>/menu/items/{menuItem}</code></td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/menu/items/position</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/menu-settings</code>, <code>/menu-locations</code>, <code>/menu-item-groups</code>, <code>/menu-item-types</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td>same resources</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/content-models</code>, <code>/content-models/{content_model}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/content-models</code>, <code>/content-models/{content_model}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/content-model/items</code>, <code>/content-model/items/{contentModelItem}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/content-model/items</code>, <code>/content-model/items/{contentModelItem}</code></td><td>Authenticated</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/content-model/user-items</code> (+ <code>/{id}</code>)</td><td>Public — visitor submission (forms)</td></tr><tr><td><code>POST</code></td><td><code>/content-model-items/list</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/content-model-items/search/{query?}/{contentModelId?}</code></td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/content-model-items/related/{contentModelItem}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/permalinks</code>, <code>/permalinks/{permalink}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/permalinks</code>, <code>/permalinks/{permalink}</code></td><td>Authenticated</td></tr></tbody></table><h2 id="news" tabindex="-1">News <a class="header-anchor" href="#news" aria-label="Permalink to &quot;News&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/news-articles</code>, <code>/news-articles/{newsArticle}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/news-articles/headlines/{limit?}</code>, <code>/news-articles/random/{limit?}</code>, <code>/news-articles/categories</code>, <code>/news-articles/search/{query?}</code>, <code>/news-articles/list/months</code></td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/news-articles/list</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/news-articles</code>, <code>/news-articles/{newsArticle}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/news-categories</code>, <code>/news-categories/{newsCategory}</code>, <code>/news-categories/articles</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/news-categories</code>, <code>/news-categories/{newsCategory}</code> (+ <code>position</code>, <code>force</code>, <code>restore</code>)</td><td>Authenticated</td></tr><tr><td><code>GET</code> <code>POST</code></td><td><code>/news-comments</code>, <code>/news-comments/{newsComment}</code></td><td>Public — including creation (<code>POST</code>)</td></tr><tr><td><code>PUT</code> <code>DELETE</code></td><td><code>/news-comments/{newsComment}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/news-tags</code>, <code>/news-tags/{newsTag}</code>, <code>/news-tags/articles</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/news-tags</code>, <code>/news-tags/{newsTag}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authenticated</td></tr></tbody></table><h2 id="videos" tabindex="-1">Videos <a class="header-anchor" href="#videos" aria-label="Permalink to &quot;Videos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/video-items</code>, <code>/video-items/{videoItem}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/video-categories</code>, <code>/video-categories/{videoCategory}</code>, <code>/video-categories/items</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/video-items</code>, <code>/video-items/{videoItem}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/video-items/youtube/channel-videos</code></td><td>Authenticated</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/video-categories</code>, <code>/video-categories/{videoCategory}</code> (+ <code>position</code>, <code>force</code>, <code>restore</code>)</td><td>Authenticated</td></tr><tr><td><code>GET</code> <code>PUT</code></td><td><code>/video-settings</code></td><td>Authenticated</td></tr></tbody></table><h2 id="ads" tabindex="-1">Ads <a class="header-anchor" href="#ads" aria-label="Permalink to &quot;Ads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/ads</code>, <code>/ads/{ad}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/ad-identifiers</code>, <code>/ad-identifiers/{ad_identifier}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/ads</code>, <code>/ads/{ad}</code></td><td>Authenticated</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/ad-identifiers</code>, <code>/ad-identifiers/{ad_identifier}</code></td><td>Authenticated</td></tr></tbody></table><h2 id="newsletter" tabindex="-1">Newsletter <a class="header-anchor" href="#newsletter" aria-label="Permalink to &quot;Newsletter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/newsletter/emails</code>, <code>/newsletter/phones</code></td><td>Public — self-subscribe</td></tr><tr><td><code>GET</code> <code>PUT</code> <code>DELETE</code></td><td><code>/newsletter/emails</code>, <code>/newsletter/phones</code> (+ <code>/{id}</code>)</td><td>Authenticated</td></tr><tr><td><code>GET</code> <code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/newsletter/campaigns</code> (+ <code>/{campaign}</code>)</td><td>Authenticated</td></tr></tbody></table><h2 id="users-roles-and-permissions" tabindex="-1">Users, roles, and permissions <a class="header-anchor" href="#users-roles-and-permissions" aria-label="Permalink to &quot;Users, roles, and permissions&quot;">​</a></h2><p>See <a href="./authentication.html#roles-and-permissions">Authentication</a> for guards and named permissions.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/roles</code>, <code>/permissions</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/roles</code>, <code>/permissions</code> (+ <code>/{id}</code>)</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/roles/user/{user?}</code>, <code>/permissions/user/{user?}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/users</code>, <code>/users/{user}</code>, <code>/users/search/{query?}</code>, <code>/users/type/administrators</code></td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/users</code>, <code>/users/import</code></td><td>Authenticated + <code>action-add-user</code> permission</td></tr><tr><td><code>PUT</code></td><td><code>/users/{user}</code></td><td>Authenticated + <code>action-edit-user</code> permission</td></tr><tr><td><code>DELETE</code></td><td><code>/users/{user}</code></td><td>Authenticated + <code>action-delete-user</code> permission</td></tr><tr><td><code>PUT</code></td><td><code>/users/self/{user}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/user/permissions/{user?}</code>, <code>/user/sessions/{user?}</code>, <code>/user/devices/{user?}</code>, <code>/user/place/{user?}</code>, <code>/user/roles/{user?}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/user/email/{email}</code>, <code>/user/phone/{phone}</code>, <code>/user/username/{username}</code></td><td>Authenticated</td></tr><tr><td><code>GET</code> <code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/user-sessions</code>, <code>/user-devices</code>, <code>/user-place</code> (+ <code>/{id}</code>)</td><td>Authenticated</td></tr></tbody></table><h2 id="media-library" tabindex="-1">Media library <a class="header-anchor" href="#media-library" aria-label="Permalink to &quot;Media library&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/media-files</code>, <code>/media-files/{mediaFile}</code>, <code>/media-files/search/{query?}</code>, <code>/media-files/list/months</code></td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/media-files/list</code>, <code>/media-files/paths/list</code>, <code>/media-files/upload</code></td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/media-files/replace/{mediaFile}</code>, <code>/media-files/delete</code></td><td>Authenticated</td></tr><tr><td><code>DELETE</code></td><td><code>/media-files/{mediaFile}</code> (+ <code>force</code>, <code>force/all</code>)</td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/media-files/restore/{mediaFile}</code></td><td>Authenticated</td></tr></tbody></table><p>No media library route is public, unlike the other content resources.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/notifications</code>, <code>/notifications/unread</code>, <code>/notifications/read</code></td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/notifications/mark/{notification}</code>, <code>/notifications/mark-all</code></td><td>Authenticated</td></tr><tr><td><code>DELETE</code></td><td><code>/notifications/{notification}</code></td><td>Authenticated</td></tr></tbody></table><h2 id="statistics" tabindex="-1">Statistics <a class="header-anchor" href="#statistics" aria-label="Permalink to &quot;Statistics&quot;">​</a></h2><p>All authenticated — power the admin panel&#39;s <a href="./../admin-panel/content-management/getting-started.html">Overview</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/visits</code>, <code>/visitors</code></td></tr><tr><td><code>GET</code></td><td><code>/count/users</code>, <code>/count/administrators</code>, <code>/count/others</code></td></tr><tr><td><code>GET</code></td><td><code>/count/news-articles</code> (+ <code>/status/{status}</code>, <code>/author/{id}</code>), <code>/count/news-categories</code>, <code>/count/news-comments</code>, <code>/count/news-tags</code></td></tr><tr><td><code>GET</code></td><td><code>/count/media-files</code> (+ <code>/type/{type}</code>, <code>/trashed</code>)</td></tr></tbody></table><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p>See <a href="./../plugins-development/basics.html#listing-installing-and-managing-plugins">Plugin Development</a> for the full lifecycle.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Access</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/plugins</code>, <code>/plugins/{id}</code></td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/plugins/install</code></td><td>Authenticated</td></tr><tr><td><code>PUT</code></td><td><code>/plugins/{id}/update</code>, <code>/plugins/{id}/enable</code>, <code>/plugins/{id}/disable</code></td><td>Authenticated</td></tr><tr><td><code>DELETE</code></td><td><code>/plugins/{id}/uninstall</code></td><td>Authenticated</td></tr></tbody></table><h2 id="miscellaneous" tabindex="-1">Miscellaneous <a class="header-anchor" href="#miscellaneous" aria-label="Permalink to &quot;Miscellaneous&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Description</th><th>Access</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/email</code></td><td>Sends an email through the configured mail driver.</td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/sms</code></td><td>Sends an SMS through the configured provider.</td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/file/upload</code>, <code>/file/replace</code>, <code>/file/delete</code>, <code>/file/download</code>, <code>/file/check</code></td><td>Upload/management of generic files (outside the media library).</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/translations/{locale}</code></td><td>Interface translation strings for a given language.</td><td>Public</td></tr><tr><td><code>GET</code> <code>PUT</code></td><td><code>/app-settings</code>, <code>/app-information</code></td><td>Global settings and <a href="./../admin-panel/content-management/platform-identity.html">platform identity</a>.</td><td>Public</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>app-settings</code>/<code>app-information</code> aren&#39;t protected by <code>auth:sanctum</code> at the route level — keep this in mind if either is extended.</p></div><h2 id="installation-server" tabindex="-1">Installation &amp; server <a class="header-anchor" href="#installation-server" aria-label="Permalink to &quot;Installation &amp; server&quot;">​</a></h2><p>These routes mainly serve the web install wizard (see <a href="./../getting-started/installation.html">Installation</a>) rather than a typical external integration.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/</code></td><td>Server health check.</td></tr><tr><td><code>POST</code></td><td><code>/server/configure</code></td><td>Initial server configuration (URL, etc.).</td></tr><tr><td><code>GET</code> <code>POST</code></td><td><code>/database</code> (+ <code>/test</code>, <code>/create</code>, <code>/migrate</code>, <code>/seed</code>)</td><td>Connection, creation, and migration of the database during installation.</td></tr><tr><td><code>POST</code></td><td><code>/install/finalize</code>, <code>/install/create-admin</code></td><td>Finalizes installation, creates the first administrator account.</td></tr></tbody></table>`,46)])])}const m=t(a,[["render",i]]);export{p as __pageData,m as default};
